<?php
defined( 'ABSPATH' ) || exit;

class Mabna_Bale_Challenge_Shortcode {
    public function __construct() {
        add_shortcode( 'mabna_challenge', [ $this, 'shortcode' ] );
        add_action( 'wp_ajax_mabna_challenge_step', [ $this, 'ajax' ] );
        add_action( 'wp_ajax_nopriv_mabna_challenge_step', [ $this, 'ajax' ] );
    }

    public function shortcode( $atts = [] ): string {
        $atts = shortcode_atts( [ 'event_id' => 0 ], $atts, 'mabna_challenge' );
        $event_id = absint( $atts['event_id'] );
        if ( ! $event_id ) { $events = Mabna_Bale_Challenge_DB::active_events(); $event_id = ! empty( $events[0]['id'] ) ? (int) $events[0]['id'] : 0; }
        $event = $event_id ? Mabna_Bale_Challenge_DB::event( $event_id ) : null;
        if ( ! $event || empty( $event['active'] ) || ! mabna_bale_event_in_window( $event ) ) return '<div class="mabna-challenge mabna-challenge-off">این چالش در حال حاضر فعال نیست.</div>';
        $nonce = wp_create_nonce( 'mabna_challenge' ); $config = $event['result_config'] ?? [];
        ob_start(); ?>
        <div class="mabna-challenge" dir="rtl" data-event="<?php echo esc_attr( $event_id ); ?>" data-nonce="<?php echo esc_attr( $nonce ); ?>">
            <div class="mabna-challenge-card"><h2><?php echo esc_html( $event['title'] ); ?></h2><div class="mabna-challenge-body"><?php echo nl2br( esc_html( $event['message'] ) ); ?></div><button type="button" class="mabna-challenge-start">🚀 شروع ماشین زمان</button></div>
            <div class="mabna-challenge-status" aria-live="polite"></div>
        </div>
        <style>.mabna-challenge{max-width:680px;margin:30px auto;font-family:inherit}.mabna-challenge-card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:28px;box-shadow:0 8px 30px rgba(0,0,0,.08)}.mabna-challenge h2{margin-top:0}.mabna-challenge-body{line-height:2;white-space:normal;margin-bottom:22px}.mabna-challenge button{border:0;border-radius:10px;padding:12px 20px;background:#2563eb;color:#fff;cursor:pointer;font-size:15px;margin:6px}.mabna-challenge .option{display:block;width:calc(100% - 12px);background:#f1f5f9;color:#111827;text-align:right}.mabna-challenge input{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:9px;padding:12px;margin:7px 0}.mabna-challenge-progress{color:#64748b;font-size:13px;margin-bottom:12px}.mabna-challenge-result img{max-width:100%;border-radius:14px}.mabna-challenge-error{color:#b91c1c;margin:10px 0}</style>
        <script>(function(){const root=document.currentScript.previousElementSibling.previousElementSibling;const status=root.querySelector('.mabna-challenge-status');const card=root.querySelector('.mabna-challenge-card');const ajax='<?php echo esc_js(admin_url('admin-ajax.php')); ?>';let token='';function post(step,data){const body=new URLSearchParams({action:'mabna_challenge_step',nonce:root.dataset.nonce,event_id:root.dataset.event,step,token,...data});return fetch(ajax,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}).then(r=>r.json())}function render(x){if(!x.success){status.innerHTML='<div class="mabna-challenge-error">'+(x.data?.message||'خطایی رخ داد.')+'</div>';return}if(x.data.token)token=x.data.token;if(x.data.html)card.innerHTML=x.data.html;if(x.data.done)status.innerHTML=x.data.html||'';bind()}function bind(){const start=root.querySelector('.mabna-challenge-start');if(start)start.onclick=()=>post('start',{}).then(render);const form=root.querySelector('form');if(form)form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));post(form.dataset.step,d).then(render)};root.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>post('answer',{index:b.dataset.index,choice:b.dataset.choice}).then(render))}bind()})();</script>
        <?php return (string) ob_get_clean();
    }

    public function ajax(): void {
        check_ajax_referer( 'mabna_challenge', 'nonce' ); $event_id=absint($_POST['event_id']??0);$event=Mabna_Bale_Challenge_DB::event($event_id);
        if(!$event||empty($event['active'])||!mabna_bale_event_in_window($event))wp_send_json_error(['message'=>'این چالش فعال نیست.']);
        $step=sanitize_key($_POST['step']??'');$token=sanitize_text_field(wp_unslash($_POST['token']??''));$session=$token?$this->get_session($token,$event_id):null;
        if($step==='start'){$token=wp_generate_password(48,false,false);$session=['event_id'=>$event_id,'chat_id'=>'web_'.hash('sha256',$token),'user_id'=>get_current_user_id(),'current_step'=>'first_name','answers'=>[],'message_ids'=>[],'status'=>'active','source'=>'shortcode','session_token_hash'=>hash('sha256',$token)];$id=Mabna_Bale_Challenge_DB::save_session($session);$session['id']=$id;$user=wp_get_current_user();$has_user=is_user_logged_in()&&$user instanceof WP_User&&$user->ID;if($has_user&&$user->first_name&&$user->last_name){$session['first_name']=$user->first_name;$session['last_name']=$user->last_name;Mabna_Bale_Challenge_DB::save_session($session);wp_send_json_success(['token'=>$token,'html'=>$this->question_html($event,$session,0)]);}wp_send_json_success(['token'=>$token,'html'=>$this->name_html()]);}
        if(!$session)wp_send_json_error(['message'=>'نشست چالش منقضی شده است؛ دوباره شروع کنید.']);
        if($step==='name'){$session['first_name']=sanitize_text_field(wp_unslash($_POST['first_name']??''));$session['last_name']=sanitize_text_field(wp_unslash($_POST['last_name']??''));if(!$session['first_name']||!$session['last_name'])wp_send_json_error(['message'=>'نام و نام خانوادگی را کامل وارد کنید.']);Mabna_Bale_Challenge_DB::save_session($session);wp_send_json_success(['html'=>$this->question_html($event,$session,0)]);}
        if($step==='answer'){$index=absint($_POST['index']??0);$choice=absint($_POST['choice']??0);$qs=mabna_bale_challenge_questions($event);if(!isset($qs[$index]['options'][$choice]))wp_send_json_error(['message'=>'پاسخ نامعتبر است.']);$session['answers'][(string)$index]=['choice'=>$choice,'text'=>$qs[$index]['options'][$choice]];Mabna_Bale_Challenge_DB::save_session($session);if($index<5)wp_send_json_success(['html'=>$this->question_html($event,$session,$index+1)]);if(!empty($session['phone'])){$html=$this->finish($event,$session);wp_send_json_success(['html'=>$html,'done'=>true]);}wp_send_json_success(['html'=>$this->phone_html()]);}
        if($step==='phone'){$phone=mabna_bale_normalize_phone((string)wp_unslash($_POST['phone']??''));if(!preg_match('/^09[0-9]{9}$/',$phone))wp_send_json_error(['message'=>'شماره تلفن معتبر وارد کنید.']);$session['phone']=$phone;$session['marketing_consent']=!empty($_POST['marketing_consent'])?1:0;$session['consent_at']=$session['marketing_consent']?current_time('mysql'):null;Mabna_Bale_Challenge_DB::save_session($session);$html=$this->finish($event,$session);wp_send_json_success(['html'=>$html,'done'=>true]);}
        wp_send_json_error(['message'=>'مرحله نامعتبر است.']);
    }
    private function get_session(string $token,int $event_id):?array{global $wpdb;$t=Mabna_Bale_Challenge_DB::tables()['sessions'];$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t} WHERE event_id=%d AND session_token_hash=%s AND status='active'",$event_id,hash('sha256',$token)),ARRAY_A);if(!$row)return null;foreach(['answers','message_ids'] as $f)$row[$f]=$row[$f]?json_decode($row[$f],true):[];return $row;}
    private function name_html():string{return '<h3>تو رو با چه اسمی بشناسیم؟</h3><p>این اسم در کارنامه آزمون نمایش داده میشه.</p><form data-step="name"><input name="first_name" placeholder="نام" required><input name="last_name" placeholder="نام خانوادگی" required><button type="submit">ادامه</button></form>';}
    private function question_html(array $event,array $session,int $index):string{$q=mabna_bale_challenge_questions($event)[$index];$html='<div class="mabna-challenge-progress">سؤال '.($index+1).' از ۶</div><h3>'.esc_html($q['text']).'</h3>';foreach($q['options'] as $i=>$o)$html.='<button class="option" type="button" data-answer data-index="'.$index.'" data-choice="'.$i.'">'.esc_html($o).'</button>';return $html;}
    private function phone_html():string{return '<h3>نویسنده موردنظر رو پیدا کردیم</h3><p>شماره‌ات رو وارد کن تا نتیجه رو بهت نشون بدیم.<br>شماره‌ات پیش ما امانته؛ نگران لو رفتن یا سوءاستفاده نباش.</p><form data-step="phone"><input name="phone" inputmode="tel" placeholder="شماره تلفن همراه" required><label><input type="checkbox" name="marketing_consent" value="1" style="width:auto"> مایل هستم اخبار و پیشنهادهای مبنا را دریافت کنم.</label><br><button type="submit">نمایش نتیجه</button></form>';}
    private function finish(array $event,array $s):string{global $wpdb;$s['status']='completed';$s['current_step']='result';$s['completed_at']=current_time('mysql');Mabna_Bale_Challenge_DB::save_session($s);$rid=Mabna_Bale_Challenge_DB::result($s,'default');$config=$event['result_config']??[];$url=$config['post_url']??'';$html='<div class="mabna-challenge-result"><p>نتیجه چالش آماده شد.</p>';if(!empty($config['image_url']))$html.='<img src="'.esc_url($config['image_url']).'" alt="نتیجه چالش">';$html.='<p>برای آموزش عبور از این مانع، روی دکمه زیر بزن.</p>';if($url)$html.='<a href="'.esc_url($url).'" target="_blank" rel="noopener"><button type="button">بزن بریم!</button></a>';return $html.'</div>';}
}
